    for x1 in range(5):
        for x2 in range(5):
            for x3 in range(5):
                if x0 + x1 + x2 + x3 == 4:
                    seq = [x0, x1, x2, x3]
                    counts = [seq.count(i) for i in range(4)]
                    if seq == counts:
                        solutions.append(seq)
